import{_ as e,f as t,h as r,O as i}from"./chunks/framework.Cc_cVMsA.js";const c=JSON.parse('{"title":"关于","description":"","frontmatter":{"title":"关于","date":"2023-07-13T17:03:00.000Z"},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),l={name:"about.md"};function n(o,a,h,p,s,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<p>欢迎访问我的个人站点，我是绝弹。本科毕业于信息工程学院，目前从事软件开发工作多年，主要方向为前端工程化与 Node.js 全栈开发。</p><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="地铁运维系统开发-·-前端负责人" tabindex="-1">地铁运维系统开发 · 前端负责人 <a class="header-anchor" href="#地铁运维系统开发-·-前端负责人" aria-label="Permalink to &quot;地铁运维系统开发 · 前端负责人&quot;">​</a></h3><p>时间：2021 – 2024 深圳市北海轨道交通技术有限公司</p><p>担任前端主要负责人，负责运维平台前端体系从零搭建到多项目交付的全过程，覆盖技术选型、基础架构、组件规范与团队协作。</p><ul><li>主导技术选型与工程架构设计，建立项目目录规范、构建配置、代码规范与协作流程，为后续多项目开发奠定统一基础。</li><li>统筹前端排期与任务拆分，带领团队完成多个业务模块的按期交付，保障系统稳定上线。</li><li>封装 Form、Table 等高频业务组件，统一交互与校验规范，减少重复开发，显著提升团队开发效率。</li><li>独立完成基于 ECharts 的日志统计等图形化模块，支撑运维数据的直观呈现与分析。</li><li>基于 ECharts 独立实现可拖拽、可缩放、可配置的地图站点编辑器，支持站点状态显示与动态更新。</li><li>基于 Web Audio API 实现话筒广播能力，完成音频采集、处理与播放链路。</li><li>独立完成面向地铁广播场景的可拖拽编辑器，支持广播内容的可视化编排。</li></ul><h3 id="工厂内部管理系统维护-·-开发人员" tabindex="-1">工厂内部管理系统维护 · 开发人员 <a class="header-anchor" href="#工厂内部管理系统维护-·-开发人员" aria-label="Permalink to &quot;工厂内部管理系统维护 · 开发人员&quot;">​</a></h3><p>时间：2019 – 2021 深圳市克莱沃电子有限公司</p><p>参与工厂内部管理系统的日常维护与功能迭代，承担部分独立功能模块的设计与实现。</p><ul><li>负责多个独立功能模块的开发与实现，按需求完成从设计到上线的完整闭环。</li><li>参与系统日常维护与问题排查，保障内部业务系统的稳定运行。</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><h3 id="前端开发" tabindex="-1">前端开发 <a class="header-anchor" href="#前端开发" aria-label="Permalink to &quot;前端开发&quot;">​</a></h3><ul><li>熟练掌握 HTML、CSS、JavaScript、TypeScript，具备扎实的 Web 基础与类型化开发能力</li><li>熟练使用 Vue.js 全家桶进行中大型应用开发，能基于 Nuxt.js 完成全栈项目搭建</li><li>熟悉 Vite 构建工具及其插件机制，具备自定义插件开发经验</li></ul><h3 id="后端开发" tabindex="-1">后端开发 <a class="header-anchor" href="#后端开发" aria-label="Permalink to &quot;后端开发&quot;">​</a></h3><ul><li>熟练使用 Node.js，能基于 NestJS 进行模块化、分层化的后端开发</li><li>熟悉 TypeORM、MySQL、Redis 等常用数据层与缓存组件，能独立完成接口设计与数据建模</li></ul><h3 id="工程化与-devops" tabindex="-1">工程化与 DevOps <a class="header-anchor" href="#工程化与-devops" aria-label="Permalink to &quot;工程化与 DevOps&quot;">​</a></h3><ul><li>熟悉 Docker、Swarm、Traefik、Portainer、Gitea 等工具，能独立搭建并维护 CI/CD 流水线</li><li>了解 Linux、Vim、Nginx、SSH 等服务器相关操作，能承担日常部署与运维工作</li></ul><h2 id="个人项目" tabindex="-1">个人项目 <a class="header-anchor" href="#个人项目" aria-label="Permalink to &quot;个人项目&quot;">​</a></h2><p>日常工作以地铁运维系统开发为主。业余时间会持续研究新技术，并通过小项目进行验证与实践。这些项目多围绕工程效率、可视化与基础设施展开，既用于沉淀技术方案，也用于解决实际使用中的问题。目前的主要项目如下。</p><h3 id="vuestarter" tabindex="-1">vuestarter <a class="header-anchor" href="#vuestarter" aria-label="Permalink to &quot;vuestarter&quot;">​</a></h3><p>地址：<a href="https://appnify.github.io/starter-vue/#/login" target="_blank" rel="noreferrer">https://appnify.github.io/starter-vue/#/login</a></p><p>基于 Arco Design 组件库，采用 Vue 3 + Vite + TypeScript 搭建的前端起始模板，内置自动路由生成、接口生成与 CRUD 组件等能力，用于快速初始化中后台项目。</p><h3 id="neststarter" tabindex="-1">neststarter <a class="header-anchor" href="#neststarter" aria-label="Permalink to &quot;neststarter&quot;">​</a></h3><p>地址：<a href="https://github.com/appnify/starter-nest" target="_blank" rel="noreferrer">https://github.com/appnify/starter-nest</a></p><p>基于 Nest + TypeORM + MySQL + Redis 的后端起始模板，集成统一参数校验、异常拦截、响应包装、分页与条件查询、Swagger 文档、JWT 鉴权、日志与邮件等通用能力，可作为服务端项目的基础脚手架。</p><h3 id="frontendnav" tabindex="-1">frontendnav <a class="header-anchor" href="#frontendnav" aria-label="Permalink to &quot;frontendnav&quot;">​</a></h3><p>地址：<a href="https://nav.juetan.cn" target="_blank" rel="noreferrer">https://nav.juetan.cn</a> 或 <a href="https://juetan.github.io/nav" target="_blank" rel="noreferrer">https://juetan.github.io/nav</a></p><p>基于 NuxtJS 开发，前端技术导航站点，收录 170+ 前端相关的技术、类库与框架资源。内容基于个人日常使用总结，覆盖语言、构建、跨端、社区、设计、命令行、后端框架与在线工具等方向。</p><h3 id="mapeditor" tabindex="-1">mapeditor <a class="header-anchor" href="#mapeditor" aria-label="Permalink to &quot;mapeditor&quot;">​</a></h3><p>地址：<a href="https://github.com/juetan/mapeditor" target="_blank" rel="noreferrer">https://github.com/juetan/mapeditor</a></p><p>基于 ECharts 实现的线点编辑器，支持拖拽、缩放与配置化编辑，可实现类似百度地铁线路图的交互效果，并支持状态显示与动态更新。</p><h3 id="appnify" tabindex="-1">appnify <a class="header-anchor" href="#appnify" aria-label="Permalink to &quot;appnify&quot;">​</a></h3><p>地址：<a href="https://github.com/appnify/appnify" target="_blank" rel="noreferrer">https://github.com/appnify/appnify</a></p><p>命令行脚手架工具，用于快速初始化项目与安装常用依赖。支持从 GitHub 仓库拉取模板，并可一键集成 eslint、prettier、husky、commitlint、lint-staged、release-it 等工程化工具。</p><h3 id="devops" tabindex="-1">devops <a class="header-anchor" href="#devops" aria-label="Permalink to &quot;devops&quot;">​</a></h3><p>地址：<a href="https://github.com/juetan/devops-practice" target="_blank" rel="noreferrer">https://github.com/juetan/devops-practice</a></p><p>基于 Docker + Portainer + Traefik + Gitea 的 CI/CD 实践系统，单台机器即可部署，支持代码提交后自动构建、发布版本、推送镜像、更新服务与配置域名，用于验证完整的持续交付流程。</p><h2 id="社区参与" tabindex="-1">社区参与 <a class="header-anchor" href="#社区参与" aria-label="Permalink to &quot;社区参与&quot;">​</a></h2><p>早期在博客园记录学习笔记，部分内容尚未迁移。知乎社区内容质量较高，常能读到有深度的技术文章；掘金前端氛围活跃，我长期关注其中的新技术与工程实践，也购买了不少课程用于系统学习。</p><ul><li>掘金社区：<a href="https://juejin.cn/user/3861140566979143" target="_blank" rel="noreferrer">https://juejin.cn/user/3861140566979143</a></li><li>博客园：<a href="https://www.cnblogs.com/juetan/" target="_blank" rel="noreferrer">https://www.cnblogs.com/juetan/</a></li><li>知乎：<a href="https://www.zhihu.com/people/luo-bu-31-18" target="_blank" rel="noreferrer">https://www.zhihu.com/people/luo-bu-31-18</a></li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>欢迎就代码交流与技术合作与我联系。</p><ul><li>微信：QQLLEE</li><li>邮箱：952222@163.com</li><li>GitHub：<a href="https://github.com/juetan" target="_blank" rel="noreferrer">https://github.com/juetan</a></li></ul><h2 id="关于本站" tabindex="-1">关于本站 <a class="header-anchor" href="#关于本站" aria-label="Permalink to &quot;关于本站&quot;">​</a></h2><p>本站基于 VitePress 深度定制，主题实现与相关说明参见：<a href="https://juetan.cn/frontend/vitepress-blog/" target="_blank" rel="noreferrer">https://juetan.cn/frontend/vitepress-blog/</a></p>',45)])])}const b=e(l,[["render",n]]);export{c as __pageData,b as default};
